-- Synthetic retail data for nlsql. Safe to drop: DROP DATABASE nlsql_demo;

CREATE DATABASE IF NOT EXISTS nlsql_demo CHARACTER SET utf8mb4;

USE nlsql_demo;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS returns;

DROP TABLE IF EXISTS payments;

DROP TABLE IF EXISTS order_items;

DROP TABLE IF EXISTS orders;

DROP TABLE IF EXISTS products;

DROP TABLE IF EXISTS categories;

DROP TABLE IF EXISTS customers;

DROP TABLE IF EXISTS employees;

DROP TABLE IF EXISTS stores;

DROP TABLE IF EXISTS regions;

SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE regions (
  id INT PRIMARY KEY,
  name VARCHAR(40) NOT NULL
) COMMENT='Sales regions';

CREATE TABLE stores (
  id INT PRIMARY KEY,
  name VARCHAR(80) NOT NULL,
  city VARCHAR(60) NOT NULL,
  region_id INT NOT NULL,
  opened_on DATE NOT NULL,
  FOREIGN KEY (region_id) REFERENCES regions(id)
) COMMENT='Physical stores; online orders have no store';

CREATE TABLE employees (
  id INT PRIMARY KEY,
  full_name VARCHAR(80) NOT NULL,
  role VARCHAR(30) NOT NULL,
  store_id INT NULL,
  manager_id INT NULL,
  hired_on DATE NOT NULL,
  salary DECIMAL(10,2) NOT NULL,
  FOREIGN KEY (store_id) REFERENCES stores(id),
  FOREIGN KEY (manager_id) REFERENCES employees(id)
);

CREATE TABLE customers (
  id INT PRIMARY KEY,
  first_name VARCHAR(40) NOT NULL,
  last_name VARCHAR(40) NOT NULL,
  email VARCHAR(120) NOT NULL UNIQUE,
  city VARCHAR(60) NOT NULL,
  segment ENUM('consumer','small_business','enterprise') NOT NULL,
  signup_date DATE NOT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 1
);

CREATE TABLE categories (
  id INT PRIMARY KEY,
  name VARCHAR(60) NOT NULL,
  parent_id INT NULL,
  FOREIGN KEY (parent_id) REFERENCES categories(id)
) COMMENT='Two-level product category tree';

CREATE TABLE products (
  id INT PRIMARY KEY,
  sku VARCHAR(20) NOT NULL UNIQUE,
  name VARCHAR(100) NOT NULL,
  category_id INT NOT NULL,
  list_price DECIMAL(10,2) NOT NULL,
  unit_cost DECIMAL(10,2) NOT NULL,
  discontinued TINYINT(1) NOT NULL DEFAULT 0,
  FOREIGN KEY (category_id) REFERENCES categories(id)
);

CREATE TABLE orders (
  id INT PRIMARY KEY,
  customer_id INT NOT NULL,
  store_id INT NULL,
  employee_id INT NULL,
  channel ENUM('online','in_store','phone') NOT NULL,
  status ENUM('pending','paid','shipped','delivered','cancelled') NOT NULL,
  ordered_at DATETIME NOT NULL,
  FOREIGN KEY (customer_id) REFERENCES customers(id),
  FOREIGN KEY (store_id) REFERENCES stores(id),
  FOREIGN KEY (employee_id) REFERENCES employees(id)
);

CREATE TABLE order_items (
  id INT PRIMARY KEY,
  order_id INT NOT NULL,
  product_id INT NOT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(10,2) NOT NULL COMMENT 'Price actually charged, after discount',
  discount_pct DECIMAL(5,2) NOT NULL DEFAULT 0,
  FOREIGN KEY (order_id) REFERENCES orders(id),
  FOREIGN KEY (product_id) REFERENCES products(id)
);

CREATE TABLE payments (
  id INT PRIMARY KEY,
  order_id INT NOT NULL,
  method ENUM('card','upi','cash','bank_transfer','wallet') NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  paid_at DATETIME NOT NULL,
  FOREIGN KEY (order_id) REFERENCES orders(id)
);

CREATE TABLE returns (
  id INT PRIMARY KEY,
  order_item_id INT NOT NULL,
  reason VARCHAR(40) NOT NULL,
  returned_at DATE NOT NULL,
  refund_amount DECIMAL(10,2) NOT NULL,
  FOREIGN KEY (order_item_id) REFERENCES order_items(id)
);



































































































































